<?php
namespace App\Services;
use App\Models\Voucher; use Illuminate\Support\Collection; use Illuminate\Validation\ValidationException;
class VoucherService {
 public function resolve(array $codes, Collection $sellerSubtotals): array { $codes=array_values(array_unique(array_filter(array_map(fn($v)=>strtoupper(trim($v)), $codes)))); if(!$codes)return[]; $vouchers=Voucher::query()->whereIn('code',$codes)->lockForUpdate()->get(); if($vouchers->count()!==count($codes))throw ValidationException::withMessages(['voucher'=>'One or more voucher codes are invalid.']); $now=now();$out=[]; foreach($vouchers as $v){if(!$v->is_active||$v->archived_at||($v->starts_at&&$v->starts_at->gt($now))||($v->expires_at&&$v->expires_at->lt($now))||($v->usage_limit!==null&&$v->used_count>=$v->usage_limit))throw ValidationException::withMessages(['voucher'=>'Voucher '.$v->code.' is unavailable.']); $eligible=$v->scope==='SELLER'?collect([$v->seller_id=>(int)$sellerSubtotals->get($v->seller_id,0)]):$sellerSubtotals; if($v->scope==='SELLER'&&(!$v->seller_id||!$eligible->sum()))throw ValidationException::withMessages(['voucher'=>'Store voucher does not match this cart.']); $base=$eligible->sum(); $amount=min($base,$this->amount($base,$v)); if(!$amount)throw ValidationException::withMessages(['voucher'=>'Voucher has no eligible merchandise.']); $allocation=$this->allocate($eligible,$amount); $out[]=['voucher'=>$v,'amount'=>$amount,'allocation'=>$allocation];} return $out; }
 private function amount(int $base,Voucher $v):int{return $v->discount_type==='PERCENTAGE'?intdiv($base*$v->discount_bps+5000,10000):$v->discount_minor;}
 private function allocate(Collection $subtotals,int $amount):array{$left=$amount;$out=[];foreach($subtotals->sortKeys() as $seller=>$subtotal){$part=min($subtotal,$left);$out[$seller]=$part;$left-=$part;}return $out;}
}
